import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type FormEvent } from 'react'
import { ArrowLeft, Check, ChevronLeft, ChevronRight, CircleAlert, Clock3, Download, FolderPlus, Gauge, LockKeyhole, Pause, Play, Plus, Redo2, RotateCcw, Send, Sparkles, Trash2, Undo2, Upload, Waypoints, X, ZoomIn } from 'lucide-react'
import WaveSurfer from 'wavesurfer.js'
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js'
import { api, ApiError, type Role, type Session } from './api'
import './workspace.css'
import './editor.css'

type Project = { id: string; code: string; name: string; description: string; status: string }
type Tier = { id: string; name: string; type: 'text' | 'controlled_vocabulary' | 'tag' | 'comment'; displayOrder: number; color: string; required: boolean; values: string[] }
type Person = { id: string; email: string; displayName: string; role: Role; projectRole?: Role }
type Recording = { id: string; projectId: string; filename: string; mediaType: string; sizeBytes: number; durationMs: number; status: string; taskStatus: string; researcherId?: string; reviewerId?: string; analysisStatus: 'not_queued' | 'queued' | 'processing' | 'completed' | 'failed' | 'cancelled'; analysisVersion?: string; analysisAttempts: number; analysisError?: string }
type Annotation = { id: string; recordingId: string; tierId: string; startMs: number; endMs: number; value: string; version: number }
type Workspace = { recording: Recording; tiers: Tier[]; annotations: Annotation[]; canEdit: boolean; canReview: boolean }
type AnalysisStatus = { jobId: string; status: 'queued' | 'processing' | 'completed' | 'failed'; algorithmVersion: string; attempts: number; errorCode?: string; durationMs?: number; pauseCount?: number; silenceMs?: number; rhythmVector?: number[]; priorityScore?: number; priorityBreakdown?: Record<string, number> }
type SignalEvent = { id: string; type: 'pause' | 'long_pause' | 'repetition_candidate' | 'speaker_turn' | 'speaker_a' | 'speaker_b'; startMs: number; endMs: number; score?: number; payload: Record<string, unknown>; reviewState: 'unreviewed' | 'confirmed' | 'rejected' | 'uncertain'; comment?: string }
type SimilarRecording = { id: string; filename: string; distance: number; priorityScore: number }
type ParticipantRole = { id: string; code: string; label: string; displayOrder: number }
type SpeakerMapping = { speakerCluster: 'speaker_a' | 'speaker_b'; participantRoleId: string; participantCode: string; participantLabel: string; mappedBy: string }
type AnalysisProfile = { version: number; silenceDbfs: number; minimumPauseMs: number; longPauseMs: number; repetitionSimilarity: number; speakerSeparation: number }
type ProfileHistory = { algorithmVersion: string; configuration: Omit<AnalysisProfile, 'version'>; queued: number; processing: number; completed: number; failed: number; createdAt: string }
type ExportHistory = { id: string; exportType: string; algorithmVersion: string; status: string; checksum?: string; requestedBy: string; createdAt: string; completedAt?: string }
const manageable = (session: Session) => session.user.role === 'superadmin' || session.user.role === 'admin'

export default function Projects({ session }: { session: Session }) {
  const [projects, setProjects] = useState<Project[]>([]); const [selected, setSelected] = useState<Project | null>(null); const [recordingId, setRecordingId] = useState<string | null>(null); const [error, setError] = useState('')
  useEffect(() => { void api<Project[]>('/api/projects').then(setProjects).catch((cause: Error) => setError(cause.message)) }, [])
  if (recordingId) return <AnnotationEditor recordingId={recordingId} session={session} onBack={() => setRecordingId(null)} />
  if (selected) return <ProjectDetail project={selected} session={session} onBack={() => setSelected(null)} onOpen={setRecordingId} />
  return <><div className="page-heading"><div><p className="eyebrow">Annotation workspace</p><h1>Projects</h1><p className="page-subtitle">Recordings, tier schemas and review work</p></div></div>{error && <p className="form-error">{error}</p>}{manageable(session) && <CreateProject session={session} onCreated={project => { setProjects(items => [...items, project]); setSelected(project) }} />}<div className="project-grid">{projects.map(project => <button key={project.id} className="project-card" onClick={() => setSelected(project)}><span className="project-code">{project.code}</span><strong>{project.name}</strong><span>{project.description || 'No description'}</span></button>)}{projects.length === 0 && <div className="empty-state"><FolderPlus size={24} /><h3>No accessible projects</h3></div>}</div></>
}

function CreateProject({ session, onCreated }: { session: Session; onCreated: (project: Project) => void }) {
  const [open, setOpen] = useState(false); const [error, setError] = useState('')
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); try { onCreated(await api<Project>('/api/projects', { method: 'POST', body: JSON.stringify({ code: data.get('code'), name: data.get('name'), description: data.get('description') }) }, session.csrfToken)) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to create project') } }
  if (!open) return <button className="primary-button workspace-action" onClick={() => setOpen(true)}><Plus size={16} />New project</button>
  return <form className="workspace-form" onSubmit={submit}><div className="section-heading"><h2>New project</h2><button type="button" className="icon-button" onClick={() => setOpen(false)} aria-label="Close"><X size={17} /></button></div><label>Code<input name="code" pattern="[a-z0-9][a-z0-9-]{1,31}" placeholder="posi-pilot" required /></label><label>Name<input name="name" maxLength={120} required /></label><label className="wide-field">Description<textarea name="description" maxLength={2000} /></label>{error && <p className="form-error wide-field">{error}</p>}<button className="primary-button" type="submit">Create project</button></form>
}

function ProjectDetail({ project, session, onBack, onOpen }: { project: Project; session: Session; onBack: () => void; onOpen: (id: string) => void }) {
  const [tiers, setTiers] = useState<Tier[]>([]); const [recordings, setRecordings] = useState<Recording[]>([]); const [people, setPeople] = useState<Person[]>([]); const [participantRoles, setParticipantRoles] = useState<ParticipantRole[]>([]); const [profile, setProfile] = useState<AnalysisProfile | null>(null); const [profileHistory, setProfileHistory] = useState<ProfileHistory[]>([]); const [exportHistory, setExportHistory] = useState<ExportHistory[]>([]); const [error, setError] = useState('')
  const refresh = async () => { try { const peopleRequest = manageable(session) ? api<Person[]>(`/api/projects/${project.id}/people`) : Promise.resolve([]); const exportRequest = manageable(session) ? api<ExportHistory[]>(`/api/projects/${project.id}/export-history`) : Promise.resolve([]); const [newTiers, newRecordings, newPeople, newParticipantRoles, newProfile, newHistory, newExports] = await Promise.all([api<Tier[]>(`/api/projects/${project.id}/tiers`), api<Recording[]>(`/api/projects/${project.id}/recordings`), peopleRequest, api<ParticipantRole[]>(`/api/projects/${project.id}/participant-roles`), api<AnalysisProfile>(`/api/projects/${project.id}/analysis-profile`), api<ProfileHistory[]>(`/api/projects/${project.id}/analysis-profile/history`), exportRequest]); setTiers(newTiers); setRecordings(newRecordings); setPeople(newPeople); setParticipantRoles(newParticipantRoles); setProfile(newProfile); setProfileHistory(newHistory); setExportHistory(newExports); setError('') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to load project') } }
  useEffect(() => { void refresh() }, [project.id])
  async function analysisAction(recording: Recording, action: 'retry' | 'cancel') { try { await api(`/api/recordings/${recording.id}/analysis/${action}`, { method: 'POST' }, session.csrfToken); await refresh() } catch (cause) { setError(cause instanceof Error ? cause.message : `Unable to ${action} analysis`) } }
  const governance = <section className="section"><div className="section-heading"><h2>Analysis governance</h2><span>{profileHistory.length} versions</span></div><div className="governance-table"><div className="governance-row governance-row--head"><span>Version</span><span>Thresholds</span><span>Jobs</span><span>Created</span></div>{profileHistory.map(item => <div className="governance-row" key={item.algorithmVersion}><strong>{item.algorithmVersion}</strong><span>{item.algorithmVersion.startsWith('signal-v3-p') ? `${item.configuration.silenceDbfs} dBFS · ${item.configuration.minimumPauseMs}/${item.configuration.longPauseMs} ms · repetition ${item.configuration.repetitionSimilarity}` : 'Legacy fixed profile'}</span><span>{item.completed} complete{item.processing + item.queued ? ` · ${item.processing + item.queued} active` : ''}{item.failed ? ` · ${item.failed} failed` : ''}</span><time dateTime={item.createdAt}>{new Date(item.createdAt).toLocaleString()}</time></div>)}</div>{manageable(session) && exportHistory.length > 0 && <><div className="section-heading governance-subheading"><h2>Export history</h2><span>{exportHistory.length} recent</span></div><div className="governance-table"><div className="governance-row governance-row--export governance-row--head"><span>Export</span><span>Version</span><span>Requested by</span><span>Checksum</span></div>{exportHistory.map(item => <div className="governance-row governance-row--export" key={item.id}><strong>{item.exportType.replaceAll('_', ' ')}</strong><span>{item.algorithmVersion}</span><span>{item.requestedBy}</span><code title={item.checksum}>{item.checksum?.slice(0, 12) || item.status}</code></div>)}</div></>}</section>
  useEffect(() => { if (!recordings.some(item => item.analysisStatus === 'queued' || item.analysisStatus === 'processing')) return; const timer = window.setInterval(() => void refresh(), 3000); return () => window.clearInterval(timer) }, [recordings, project.id])
  return <><button className="text-button back-button" onClick={onBack}><ArrowLeft size={16} />Projects</button><div className="page-heading"><div><p className="eyebrow">{project.code}</p><h1>{project.name}</h1><p className="page-subtitle">{project.description || 'Annotation project'}</p></div></div>{error && <p className="form-error">{error}</p>}{manageable(session) && <section className="section"><div className="section-heading"><h2>Project team</h2><span>{people.filter(person => person.projectRole).length} assigned</span></div><MemberManager projectId={project.id} people={people} session={session} onChanged={() => void refresh()} /></section>}<section className="section"><div className="section-heading"><h2>Participant roles</h2><span>{participantRoles.length} labels</span></div><div className="participant-role-list">{participantRoles.map(role => <span key={role.id}><strong>{role.label}</strong>{role.code}</span>)}</div>{manageable(session) && <ParticipantRoleForm projectId={project.id} session={session} order={participantRoles.length} onCreated={() => void refresh()} />}</section>{profile && <section className="section"><div className="section-heading"><h2>Analysis profile</h2><span>Version {profile.version}</span></div><AnalysisProfileForm projectId={project.id} session={session} profile={profile} editable={manageable(session)} onUpdated={updated => { setProfile(updated); void refresh() }} /></section>}{governance}<section className="section"><div className="section-heading"><h2>Tier schema</h2><span>{tiers.length} tiers</span></div><div className="tier-key">{tiers.map(tier => <span key={tier.id}><i style={{ background: tier.color }} />{tier.name}{tier.required ? ' *' : ''}</span>)}</div>{manageable(session) && <TierForm projectId={project.id} session={session} order={tiers.length} onCreated={() => void refresh()} />}</section><section className="section"><div className="section-heading"><h2>Recordings</h2><div className="recording-heading-actions"><span>{recordings.length} items</span><a href={`/api/projects/${project.id}/exports/summary.csv`}><Download size={14} />Summary CSV</a><a href={`/api/projects/${project.id}/exports/batch.zip`}><Download size={14} />Batch ZIP</a></div></div><div className="recording-list">{recordings.map(item => <div key={item.id} className="recording-row"><button className="recording-open" onClick={() => onOpen(item.id)}><strong>{item.filename}</strong><span>{(item.durationMs / 1000).toFixed(2)} seconds</span></button><span className={`analysis-state analysis-state--${item.analysisStatus}`} title={item.analysisError || item.analysisVersion}>{item.analysisStatus.replace('_', ' ')}</span><span className={`task-state task-state--${item.taskStatus}`}>{item.taskStatus.replace('_', ' ')}</span>{manageable(session) && item.analysisStatus === 'queued' && <button className="icon-button" title="Cancel queued analysis" aria-label={`Cancel analysis for ${item.filename}`} onClick={() => void analysisAction(item, 'cancel')}><X size={15} /></button>}{manageable(session) && (item.analysisStatus === 'failed' || item.analysisStatus === 'cancelled') && <button className="icon-button" title="Retry analysis" aria-label={`Retry analysis for ${item.filename}`} onClick={() => void analysisAction(item, 'retry')}><RotateCcw size={15} /></button>}</div>)}</div>{manageable(session) && <RecordingUpload projectId={project.id} session={session} people={people} onCreated={() => void refresh()} />}</section></>
}

function AnalysisProfileForm({ projectId, session, profile, editable, onUpdated }: { projectId: string; session: Session; profile: AnalysisProfile; editable: boolean; onUpdated: (profile: AnalysisProfile) => void }) {
  const [draft, setDraft] = useState(profile); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('')
  useEffect(() => setDraft(profile), [profile])
  const field = (key: keyof AnalysisProfile, value: string) => setDraft(current => ({ ...current, [key]: Number(value) }))
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(''); setMessage(''); try { const updated = await api<AnalysisProfile>(`/api/projects/${projectId}/analysis-profile`, { method: 'PUT', body: JSON.stringify({ silenceDbfs: draft.silenceDbfs, minimumPauseMs: draft.minimumPauseMs, longPauseMs: draft.longPauseMs, repetitionSimilarity: draft.repetitionSimilarity, speakerSeparation: draft.speakerSeparation, version: draft.version }) }, session.csrfToken); onUpdated(updated); setMessage(`Version ${updated.version} queued for all recordings`) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to update analysis profile') } finally { setBusy(false) } }
  return <form className="analysis-profile" onSubmit={submit}><label>Silence threshold<input type="number" min="-80" max="-10" step="0.5" value={draft.silenceDbfs} disabled={!editable} onChange={event => field('silenceDbfs', event.target.value)} /><small>dBFS</small></label><label>Minimum pause<input type="number" min="100" max="10000" step="100" value={draft.minimumPauseMs} disabled={!editable} onChange={event => field('minimumPauseMs', event.target.value)} /><small>milliseconds</small></label><label>Long pause<input type="number" min="500" max="60000" step="100" value={draft.longPauseMs} disabled={!editable} onChange={event => field('longPauseMs', event.target.value)} /><small>milliseconds</small></label><label>Repetition match<input type="number" min="0.5" max="0.99" step="0.01" value={draft.repetitionSimilarity} disabled={!editable} onChange={event => field('repetitionSimilarity', event.target.value)} /><small>similarity</small></label><label>Speaker separation<input type="number" min="0.1" max="5" step="0.1" value={draft.speakerSeparation} disabled={!editable} onChange={event => field('speakerSeparation', event.target.value)} /><small>distance</small></label>{editable && <button className="primary-button" type="submit" disabled={busy || draft.longPauseMs < draft.minimumPauseMs}><RotateCcw size={15} />{busy ? 'Queuing…' : 'Save and reanalyze'}</button>}{message && <p className="profile-message">{message}</p>}{error && <p className="form-error">{error}</p>}</form>
}

function ParticipantRoleForm({ projectId, session, order, onCreated }: { projectId: string; session: Session; order: number; onCreated: () => void }) {
  const [error, setError] = useState('')
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); try { await api(`/api/projects/${projectId}/participant-roles`, { method: 'POST', body: JSON.stringify({ code: data.get('code'), label: data.get('label'), displayOrder: order }) }, session.csrfToken); form.reset(); onCreated() } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to create participant role') } }
  return <form className="participant-role-form" onSubmit={submit}><input name="label" maxLength={80} placeholder="Display label, e.g. Teacher" required /><input name="code" pattern="[a-z][a-z0-9_-]{1,31}" placeholder="code, e.g. teacher" required /><button className="secondary-button" type="submit"><Plus size={15} />Add role</button>{error && <p className="form-error">{error}</p>}</form>
}

function MemberManager({ projectId, people, session, onChanged }: { projectId: string; people: Person[]; session: Session; onChanged: () => void }) {
  const [userId, setUserId] = useState(''); const [error, setError] = useState(''); const available = people.filter(person => !person.projectRole)
  async function assign() { const person = people.find(item => item.id === userId); if (!person) return; try { await api(`/api/projects/${projectId}/members`, { method: 'POST', body: JSON.stringify({ userId, responsibility: person.role }) }, session.csrfToken); setUserId(''); onChanged() } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to assign member') } }
  return <><div className="member-list">{people.filter(person => person.projectRole).map(person => <span key={person.id}><strong>{person.displayName}</strong>{person.projectRole}</span>)}</div><div className="member-add"><select value={userId} onChange={event => setUserId(event.target.value)}><option value="">Select researcher or reviewer</option>{available.map(person => <option key={person.id} value={person.id}>{person.displayName} · {person.role}</option>)}</select><button className="secondary-button" type="button" disabled={!userId} onClick={() => void assign()}><Plus size={15} />Assign</button></div>{error && <p className="form-error">{error}</p>}</>
}

function TierForm({ projectId, session, order, onCreated }: { projectId: string; session: Session; order: number; onCreated: () => void }) {
  const [type, setType] = useState<Tier['type']>('text'); const [error, setError] = useState('')
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); const values = String(data.get('values') || '').split(',').map(v => v.trim()).filter(Boolean); try { await api(`/api/projects/${projectId}/tiers`, { method: 'POST', body: JSON.stringify({ name: data.get('name'), type, displayOrder: order, color: data.get('color'), required: data.get('required') === 'on', values }) }, session.csrfToken); form.reset(); setType('text'); onCreated() } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to create tier') } }
  return <form className="inline-workspace-form" onSubmit={submit}><input name="name" maxLength={80} placeholder="Tier name" required /><select value={type} onChange={event => setType(event.target.value as Tier['type'])}><option value="text">Free text</option><option value="controlled_vocabulary">Controlled vocabulary</option><option value="tag">Tag</option><option value="comment">Comment</option></select><input name="color" type="color" defaultValue="#39745a" aria-label="Tier color" />{type === 'controlled_vocabulary' && <input name="values" placeholder="Allowed values, comma separated" required />}<label className="check-label"><input name="required" type="checkbox" />Required</label><button className="primary-button" type="submit"><Plus size={15} />Add tier</button>{error && <p className="form-error">{error}</p>}</form>
}

async function audioDuration(file: File): Promise<number> { return new Promise((resolve, reject) => { const audio = document.createElement('audio'); const url = URL.createObjectURL(file); audio.preload = 'metadata'; audio.onloadedmetadata = () => { URL.revokeObjectURL(url); Number.isFinite(audio.duration) && audio.duration > 0 ? resolve(Math.round(audio.duration * 1000)) : reject(new Error('Unable to read audio duration')) }; audio.onerror = () => { URL.revokeObjectURL(url); reject(new Error('The browser could not decode this audio file')) }; audio.src = url }) }

function RecordingUpload({ projectId, session, people, onCreated }: { projectId: string; session: Session; people: Person[]; onCreated: () => void }) {
  type QueueItem = { file: File; state: 'waiting' | 'reading' | 'uploading' | 'complete' | 'failed'; error?: string }
  const [queue, setQueue] = useState<QueueItem[]>([]); const [researcherId, setResearcherId] = useState(''); const [reviewerId, setReviewerId] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const researchers = people.filter(person => person.projectRole === 'researcher'); const reviewers = people.filter(person => person.projectRole === 'reviewer')
  const update = (index: number, change: Partial<QueueItem>) => setQueue(items => items.map((item, position) => position === index ? { ...item, ...change } : item))
  async function upload(item: QueueItem, index: number) { try { update(index, { state: 'reading', error: undefined }); const durationMs = await audioDuration(item.file); update(index, { state: 'uploading' }); const body = new FormData(); body.append('audio', item.file); body.append('durationMs', String(durationMs)); if (researcherId) body.append('researcherId', researcherId); if (reviewerId) body.append('reviewerId', reviewerId); const response = await fetch(`/api/projects/${projectId}/recordings/upload`, { method: 'POST', body, credentials: 'same-origin', headers: { 'X-Requested-With': 'AudioSpeechVault', 'X-CSRF-Token': session.csrfToken } }); if (!response.ok) { const result = await response.json().catch(() => ({})) as { error?: string }; throw new ApiError(response.status, result.error || 'Upload failed') } update(index, { state: 'complete' }); return true } catch (cause) { update(index, { state: 'failed', error: cause instanceof Error ? cause.message : 'Upload failed' }); return false } }
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!queue.length) return; setBusy(true); setError(''); let completed = 0; for (let index = 0; index < queue.length; index++) { if (queue[index].state === 'complete') continue; if (await upload(queue[index], index)) completed++ } setBusy(false); if (completed) onCreated(); if (completed === queue.filter(item => item.state !== 'complete').length) window.setTimeout(() => setQueue([]), 800) }
  return <form className="upload-form" onSubmit={submit}><label className="file-picker"><Upload size={19} /><span>{queue.length ? `${queue.length} file${queue.length === 1 ? '' : 's'} selected` : 'Choose MP3, WAV, FLAC, OGG or WebM files'}</span><input type="file" multiple accept=".mp3,.wav,.flac,.ogg,.webm,audio/*" onChange={event => { const files = Array.from(event.target.files || []).slice(0, 25); setQueue(files.map(file => ({ file, state: 'waiting' }))); setError(event.target.files && event.target.files.length > 25 ? 'A batch can contain up to 25 files' : '') }} required /></label><select value={researcherId} disabled={busy} onChange={event => setResearcherId(event.target.value)}><option value="">No researcher assigned</option>{researchers.map(person => <option key={person.id} value={person.id}>{person.displayName}</option>)}</select><select value={reviewerId} disabled={busy} onChange={event => setReviewerId(event.target.value)}><option value="">No reviewer assigned</option>{reviewers.map(person => <option key={person.id} value={person.id}>{person.displayName}</option>)}</select><button className="primary-button" type="submit" disabled={!queue.length || busy}>{busy ? 'Uploading batch…' : `Upload ${queue.length || ''} recording${queue.length === 1 ? '' : 's'}`}</button>{queue.length > 0 && <div className="upload-queue">{queue.map((item, index) => <div className={`upload-item upload-item--${item.state}`} key={`${item.file.name}-${item.file.lastModified}`}><span><strong>{item.file.name}</strong><small>{(item.file.size / 1024 / 1024).toFixed(1)} MB</small></span><em>{item.error || item.state}</em>{!busy && <button type="button" className="icon-button" aria-label={`Remove ${item.file.name}`} onClick={() => setQueue(items => items.filter((_, position) => position !== index))}><X size={14} /></button>}</div>)}</div>}{error && <p className="form-error">{error}</p>}</form>
}

function formatTime(milliseconds: number) {
  const safe = Math.max(0, milliseconds)
  const minutes = Math.floor(safe / 60_000)
  const seconds = Math.floor((safe % 60_000) / 1000)
  const millis = Math.floor(safe % 1000)
  return `${minutes}:${seconds.toString().padStart(2, '0')}.${millis.toString().padStart(3, '0')}`
}

function Waveform({ recordingId, durationMs, disabled, onSelect, jumpTo }: { recordingId: string; durationMs: number; disabled: boolean; onSelect: (start: number, end: number) => void; jumpTo: { startMs: number; endMs: number; nonce: number } | null }) {
  const container = useRef<HTMLDivElement>(null)
  const wave = useRef<WaveSurfer | null>(null)
  const callback = useRef(onSelect)
  const selection = useRef<{ start: number; end: number } | null>(null)
  const loopRef = useRef(false)
  const [playing, setPlaying] = useState(false)
  const [ready, setReady] = useState(false)
  const [currentMs, setCurrentMs] = useState(0)
  const [zoom, setZoom] = useState(36)
  const [speed, setSpeed] = useState(1)
  const [looping, setLooping] = useState(false)
  const [error, setError] = useState('')
  callback.current = onSelect
  loopRef.current = looping

  useEffect(() => {
    if (!container.current) return
    let destroyed = false
    let instance: WaveSurfer | null = null
    void api<{ duration: number; peaks: number[][] }>(`/api/recordings/${recordingId}/waveform`).catch(() => null).then(precomputed => {
      if (destroyed || !container.current) return
      const regions = RegionsPlugin.create()
      instance = WaveSurfer.create({ container: container.current, url: `/api/recordings/${recordingId}/media`, ...(precomputed ? { peaks: precomputed.peaks, duration: precomputed.duration } : {}), height: 156, waveColor: '#98aca3', progressColor: '#176b52', cursorColor: '#d15b44', cursorWidth: 2, barWidth: 2, barGap: 1, barRadius: 1, minPxPerSec: 36, normalize: true, plugins: [regions] })
      wave.current = instance
      if (!disabled) regions.enableDragSelection({ color: 'rgba(35, 113, 168, .16)' })
      const select = (region: { start: number; end: number; id: string }) => { regions.getRegions().filter(other => other.id !== region.id).forEach(other => other.remove()); selection.current = { start: region.start, end: region.end }; callback.current(Math.round(region.start * 1000), Math.round(region.end * 1000)) }
      regions.on('region-created', select); regions.on('region-updated', select)
      instance.on('ready', () => setReady(true)); instance.on('play', () => setPlaying(true)); instance.on('pause', () => setPlaying(false))
      instance.on('timeupdate', seconds => { setCurrentMs(Math.round(seconds * 1000)); const range = selection.current; if (loopRef.current && range && seconds >= range.end - 0.025) void instance?.play(range.start, range.end) })
      instance.on('error', () => setError('Unable to load this audio recording'))
    })
    return () => { destroyed = true; instance?.destroy() }
  }, [recordingId, disabled])

  useEffect(() => {
    const handleKey = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement
      if (event.code !== 'Space' || ['INPUT', 'SELECT', 'TEXTAREA', 'BUTTON'].includes(target.tagName)) return
      event.preventDefault()
      void wave.current?.playPause()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [])

  useEffect(() => {
    if (!jumpTo || !wave.current) return
    const start = jumpTo.startMs / 1000
    const end = jumpTo.endMs / 1000
    wave.current.setTime(start)
    void wave.current.play(start, end)
  }, [jumpTo])

  function seek(delta: number) {
    const instance = wave.current
    if (instance) instance.setTime(Math.max(0, Math.min(instance.getDuration(), instance.getCurrentTime() + delta)))
  }

  function playSelection() {
    const range = selection.current
    if (range) void wave.current?.play(range.start, range.end)
  }

  return <div className="waveform-panel">
    <div className="transport-bar">
      <div className="transport-group">
        <button className="icon-button" type="button" onClick={() => seek(-2)} title="Back 2 seconds" aria-label="Back 2 seconds"><ChevronLeft size={19} /></button>
        <button className="transport-play" type="button" disabled={!ready} onClick={() => void wave.current?.playPause()} title={playing ? 'Pause (Space)' : 'Play (Space)'} aria-label={playing ? 'Pause' : 'Play'}>{playing ? <Pause size={19} /> : <Play size={19} />}</button>
        <button className="icon-button" type="button" onClick={() => seek(2)} title="Forward 2 seconds" aria-label="Forward 2 seconds"><ChevronRight size={19} /></button>
      </div>
      <output className="timecode" aria-label="Current playback time">{formatTime(currentMs)} <span>/ {formatTime(durationMs)}</span></output>
      <div className="transport-tools">
        <button className={`tool-toggle ${looping ? 'tool-toggle--active' : ''}`} type="button" disabled={!selection.current} onClick={() => setLooping(value => !value)} title="Loop selected interval"><RotateCcw size={15} />Loop</button>
        <button className="tool-toggle" type="button" disabled={!selection.current} onClick={playSelection} title="Play selected interval"><Play size={14} />Selection</button>
        <label className="compact-control"><Gauge size={15} /><span>Speed</span><select value={speed} onChange={event => { const value = Number(event.target.value); setSpeed(value); wave.current?.setPlaybackRate(value) }}><option value="0.75">0.75x</option><option value="1">1x</option><option value="1.25">1.25x</option><option value="1.5">1.5x</option><option value="2">2x</option></select></label>
        <label className="zoom-control"><ZoomIn size={15} /><span>Zoom</span><input type="range" min="10" max="180" value={zoom} onChange={event => { const value = Number(event.target.value); setZoom(value); wave.current?.zoom(value) }} /></label>
      </div>
    </div>
    <div className="waveform-instruction">{disabled ? <><LockKeyhole size={14} />Read-only recording</> : 'Drag across the waveform to define an annotation interval'}</div>
    <div ref={container} className="waveform" />
    {error && <p className="form-error">{error}</p>}
  </div>
}

function AnnotationEditor({ recordingId, session, onBack }: { recordingId: string; session: Session; onBack: () => void }) {
  type HistoryAction = { kind: 'create' | 'update' | 'delete'; before?: Annotation; after?: Annotation; current: Annotation }
  const [space, setSpace] = useState<Workspace | null>(null); const [editing, setEditing] = useState<Annotation | null>(null); const [tierId, setTierId] = useState(''); const [startMs, setStartMs] = useState(0); const [endMs, setEndMs] = useState(1000); const [value, setValue] = useState(''); const [tierWidth, setTierWidth] = useState(165); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [saveState, setSaveState] = useState<'saved' | 'unsaved' | 'saving'>('saved'); const [analysis, setAnalysis] = useState<AnalysisStatus | null>(null); const [signalEvents, setSignalEvents] = useState<SignalEvent[]>([]); const [similar, setSimilar] = useState<SimilarRecording[]>([]); const [participantRoles, setParticipantRoles] = useState<ParticipantRole[]>([]); const [speakerMappings, setSpeakerMappings] = useState<SpeakerMapping[]>([]); const [eventType, setEventType] = useState(''); const [eventReview, setEventReview] = useState(''); const [jumpTo, setJumpTo] = useState<{ startMs: number; endMs: number; nonce: number } | null>(null); const [undoStack, setUndoStack] = useState<HistoryAction[]>([]); const [redoStack, setRedoStack] = useState<HistoryAction[]>([]); const autosaveGeneration = useRef(0)
  const refresh = () => api<Workspace>(`/api/recordings/${recordingId}/workspace`).then(setSpace).catch((cause: Error) => setError(cause.message)); useEffect(() => { void refresh() }, [recordingId]); useEffect(() => { if (space && !tierId) { setTierId(space.tiers[0]?.id || ''); setEndMs(Math.min(1000, space.recording.durationMs)) } }, [space, tierId]); useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (saveState === 'unsaved') event.preventDefault() }; window.addEventListener('beforeunload', warn); return () => window.removeEventListener('beforeunload', warn) }, [saveState]); const grouped = useMemo(() => new Map((space?.tiers || []).map(tier => [tier.id, (space?.annotations || []).filter(a => a.tierId === tier.id)])), [space])
  const invalidRange = startMs < 0 || endMs <= startMs || endMs > (space?.recording.durationMs || 0)
  async function persist(recordHistory = true) { if (!space?.canEdit || invalidRange || !tierId || !value.trim() || saveState === 'saving') return; const before = editing ? { ...editing } : undefined; const generation = ++autosaveGeneration.current; setError(''); setSaveState('saving'); try { const saved = await api<Annotation>(`/api/recordings/${recordingId}/annotations${editing ? `/${editing.id}` : ''}`, { method: editing ? 'PATCH' : 'POST', body: JSON.stringify({ tierId, startMs, endMs, value, version: editing?.version }) }, session.csrfToken); if (generation !== autosaveGeneration.current) return; setEditing(saved); if (recordHistory) { setUndoStack(items => [...items.slice(-49), { kind: before ? 'update' : 'create', before, after: saved, current: saved }]); setRedoStack([]) } await refresh(); setSaveState('saved') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to save annotation'); setSaveState('unsaved') } }
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); await persist() }
  async function action(path: string, body?: object) { setError(''); try { const result = await api<{ message: string }>(`/api/recordings/${recordingId}/${path}`, { method: 'POST', body: body ? JSON.stringify(body) : undefined }, session.csrfToken); setMessage(result.message); await refresh() } catch (cause) { setError(cause instanceof Error ? cause.message : 'Action failed') } }
  function edit(item: Annotation) { if (!space?.canEdit) return; setEditing(item); setTierId(item.tierId); setStartMs(item.startMs); setEndMs(item.endMs); setValue(item.value); setSaveState('saved') }
  async function applyHistory(action: HistoryAction, undoing: boolean) { const target = undoing ? action.before : action.after; let current: Annotation; if (action.kind === 'create') { current = undoing ? await api<Annotation>(`/api/recordings/${recordingId}/annotations/${action.current.id}`, { method: 'DELETE', body: JSON.stringify({ version: action.current.version }) }, session.csrfToken) : await api<Annotation>(`/api/recordings/${recordingId}/annotations/${action.current.id}/restore`, { method: 'POST', body: JSON.stringify({ version: action.current.version }) }, session.csrfToken) } else if (action.kind === 'delete') { current = undoing ? await api<Annotation>(`/api/recordings/${recordingId}/annotations/${action.current.id}/restore`, { method: 'POST', body: JSON.stringify({ version: action.current.version }) }, session.csrfToken) : await api<Annotation>(`/api/recordings/${recordingId}/annotations/${action.current.id}`, { method: 'DELETE', body: JSON.stringify({ version: action.current.version }) }, session.csrfToken) } else { if (!target) return; current = await api<Annotation>(`/api/recordings/${recordingId}/annotations/${action.current.id}`, { method: 'PATCH', body: JSON.stringify({ tierId: target.tierId, startMs: target.startMs, endMs: target.endMs, value: target.value, version: action.current.version }) }, session.csrfToken) } return { ...action, current } }
  async function undo() { const action = undoStack.at(-1); if (!action || saveState === 'saving') return; try { setSaveState('saving'); const updated = await applyHistory(action, true); if (!updated) return; setUndoStack(items => items.slice(0, -1)); setRedoStack(items => [...items, updated]); setEditing(null); setValue(''); await refresh(); setSaveState('saved') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to undo'); setSaveState('saved') } }
  async function redo() { const action = redoStack.at(-1); if (!action || saveState === 'saving') return; try { setSaveState('saving'); const updated = await applyHistory(action, false); if (!updated) return; setRedoStack(items => items.slice(0, -1)); setUndoStack(items => [...items, updated]); setEditing(null); setValue(''); await refresh(); setSaveState('saved') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to redo'); setSaveState('saved') } }
  async function removeAnnotation() { if (!editing) return; try { const deleted = await api<Annotation>(`/api/recordings/${recordingId}/annotations/${editing.id}`, { method: 'DELETE', body: JSON.stringify({ version: editing.version }) }, session.csrfToken); setUndoStack(items => [...items.slice(-49), { kind: 'delete', before: editing, current: deleted }]); setRedoStack([]); setEditing(null); setValue(''); await refresh(); setSaveState('saved') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to delete annotation') } }
  useEffect(() => { if (saveState !== 'unsaved' || !value.trim() || invalidRange) return; const timer = window.setTimeout(() => void persist(), 1200); return () => window.clearTimeout(timer) }, [saveState, value, tierId, startMs, endMs, editing?.version, invalidRange])
  useEffect(() => { const keyboard = (event: KeyboardEvent) => { if (!(event.ctrlKey || event.metaKey)) return; const key = event.key.toLowerCase(); if (key === 's') { event.preventDefault(); void persist() } else if (key === 'z' && !event.shiftKey) { event.preventDefault(); void undo() } else if (key === 'y' || (key === 'z' && event.shiftKey)) { event.preventDefault(); void redo() } }; window.addEventListener('keydown', keyboard); return () => window.removeEventListener('keydown', keyboard) }, [saveState, value, tierId, startMs, endMs, editing, undoStack, redoStack, invalidRange])
  const refreshSignals = useCallback(async () => {
    try {
      const [nextAnalysis, events] = await Promise.all([
        api<AnalysisStatus>(`/api/recordings/${recordingId}/analysis`),
        api<SignalEvent[]>(`/api/recordings/${recordingId}/signal-events?type=${encodeURIComponent(eventType)}&reviewState=${encodeURIComponent(eventReview)}`),
      ])
      setAnalysis(nextAnalysis)
      setSignalEvents(events)
      if (nextAnalysis.status === 'completed') setSimilar(await api<SimilarRecording[]>(`/api/recordings/${recordingId}/similar`).catch(() => []))
    } catch (cause) {
      if (!(cause instanceof ApiError && cause.status === 404)) setError(cause instanceof Error ? cause.message : 'Unable to load signal analysis')
    }
  }, [recordingId, eventType, eventReview])
  useEffect(() => { void refreshSignals() }, [refreshSignals])
  useEffect(() => { if (!space) return; void Promise.all([api<ParticipantRole[]>(`/api/projects/${space.recording.projectId}/participant-roles`), api<SpeakerMapping[]>(`/api/recordings/${recordingId}/speaker-mappings`)]).then(([roles, mappings]) => { setParticipantRoles(roles); setSpeakerMappings(mappings) }).catch((cause: Error) => setError(cause.message)) }, [space?.recording.projectId, recordingId])
  useEffect(() => { if (analysis?.status !== 'queued' && analysis?.status !== 'processing') return; const timer = window.setInterval(() => void refreshSignals(), 3000); return () => window.clearInterval(timer) }, [analysis?.status, refreshSignals])
  async function reviewSignal(event: SignalEvent, state: SignalEvent['reviewState']) { try { await api(`/api/recordings/${recordingId}/signal-events/${event.id}/review`, { method: 'POST', body: JSON.stringify({ state, comment: '' }) }, session.csrfToken); await refreshSignals() } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to review signal event') } }
  async function mapSpeaker(speakerCluster: 'speaker_a' | 'speaker_b', participantRoleId: string) { if (!participantRoleId) return; try { await api(`/api/recordings/${recordingId}/speaker-mappings`, { method: 'PUT', body: JSON.stringify({ speakerCluster, participantRoleId }) }, session.csrfToken); setSpeakerMappings(await api<SpeakerMapping[]>(`/api/recordings/${recordingId}/speaker-mappings`)) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to map speaker') } }
  if (!space) return <><button className="text-button back-button" onClick={onBack}><ArrowLeft size={16} />Project</button>{error || 'Loading workspace…'}</>
  const requiredMissing = space.tiers.filter(tier => tier.required && (grouped.get(tier.id) || []).length === 0)
  const markChanged = () => setSaveState('unsaved')
  return <div className="editor-workspace">
    <header className="editor-header">
      <button className="text-button" onClick={onBack}><ArrowLeft size={16} />Project</button>
      <div className="editor-title"><span>Annotation editor</span><h1>{space.recording.filename}</h1></div>
      <div className="editor-meta"><span className={`analysis-state analysis-state--${analysis?.status || 'queued'}`}><Sparkles size={12} />{analysis?.status === 'completed' ? `${signalEvents.length} filtered events` : analysis?.status || 'Analysis queued'}</span>{analysis?.priorityScore !== undefined && <span className="priority-state">Priority {analysis.priorityScore.toFixed(1)}</span>}<span className={`save-state save-state--${saveState}`}>{saveState === 'saving' ? 'Saving…' : saveState === 'unsaved' ? 'Unsaved changes' : 'All changes saved'}</span><span className={`task-state task-state--${space.recording.taskStatus}`}>{space.recording.taskStatus.replace('_', ' ')}</span></div>
      {space.canEdit && <button className="primary-button" disabled={saveState !== 'saved' || space.tiers.length === 0 || requiredMissing.length > 0} onClick={() => void action('submit')} title={space.tiers.length === 0 ? 'Create a tier schema before submitting' : requiredMissing.length ? 'Complete all required tiers before submitting' : 'Submit this recording for review'}><Send size={16} />Submit for review</button>}
    </header>
    {error && <p className="form-error" role="alert">{error}</p>}{message && <p className="success-message">{message}</p>}
    <Waveform recordingId={recordingId} durationMs={space.recording.durationMs} disabled={!space.canEdit} jumpTo={jumpTo} onSelect={(start, end) => { setStartMs(start); setEndMs(end); markChanged() }} />
    <section className="signal-review" aria-labelledby="signal-events-heading">
      <div className="signal-review-heading"><div><span>Local deterministic analysis</span><h2 id="signal-events-heading">Signal events</h2></div><div className="signal-filters"><select aria-label="Filter event type" value={eventType} onChange={event => setEventType(event.target.value)}><option value="">All event types</option><option value="pause">Pause</option><option value="long_pause">Long pause</option><option value="repetition_candidate">Repetition candidate</option><option value="speaker_turn">Speaker turn</option><option value="speaker_a">Speaker A</option><option value="speaker_b">Speaker B</option></select><select aria-label="Filter review state" value={eventReview} onChange={event => setEventReview(event.target.value)}><option value="">All review states</option><option value="unreviewed">Unreviewed</option><option value="confirmed">Confirmed</option><option value="rejected">Rejected</option><option value="uncertain">Uncertain</option></select></div></div>
      {analysis?.status === 'failed' && <div className="signal-empty signal-empty--error"><CircleAlert size={18} />Analysis failed. An administrator can retry this recording.</div>}
      {(analysis?.status === 'queued' || analysis?.status === 'processing') && <div className="signal-empty"><Sparkles size={18} />{analysis.status === 'queued' ? 'Waiting for the local analysis worker' : 'Inspecting the audio signal locally'}</div>}
      {analysis?.status === 'completed' && signalEvents.length === 0 && <div className="signal-empty"><Check size={18} />No events match the selected filters.</div>}
      {signalEvents.length > 0 && <div className="signal-event-list">{signalEvents.map(event => <div className={`signal-event signal-event--${event.reviewState}`} key={event.id}><button className="signal-event-main" type="button" onClick={() => setJumpTo({ startMs: event.startMs, endMs: event.endMs, nonce: Date.now() })}><Play size={15} /><span><strong>{event.type.replaceAll('_', ' ')}</strong><small>{formatTime(event.startMs)} – {formatTime(event.endMs)} · {formatTime(event.endMs - event.startMs)}</small></span></button><span className="event-review-state">{event.reviewState}</span><div className="event-review-actions"><button type="button" className={event.reviewState === 'confirmed' ? 'active' : ''} onClick={() => void reviewSignal(event, 'confirmed')} title="Confirm candidate" aria-label={`Confirm ${event.type}`}><Check size={14} /></button><button type="button" className={event.reviewState === 'uncertain' ? 'active' : ''} onClick={() => void reviewSignal(event, 'uncertain')} title="Mark uncertain" aria-label={`Mark ${event.type} uncertain`}><CircleAlert size={14} /></button><button type="button" className={event.reviewState === 'rejected' ? 'active' : ''} onClick={() => void reviewSignal(event, 'rejected')} title="Reject candidate" aria-label={`Reject ${event.type}`}><X size={14} /></button></div></div>)}</div>}
    </section>
    {signalEvents.some(event => event.type === 'speaker_a' || event.type === 'speaker_b') && <section className="speaker-mapping"><div><span>Human confirmation</span><h2>Map acoustic speaker clusters</h2><p>Speaker A/B are anonymous signal clusters. Assign participant identities only after listening.</p></div>{(['speaker_a', 'speaker_b'] as const).map(cluster => { const mapping = speakerMappings.find(item => item.speakerCluster === cluster); return <label key={cluster}><strong>{cluster === 'speaker_a' ? 'Speaker A' : 'Speaker B'}</strong><select value={mapping?.participantRoleId || ''} disabled={session.user.role === 'researcher'} onChange={event => void mapSpeaker(cluster, event.target.value)}><option value="">Not mapped</option>{participantRoles.map(role => <option value={role.id} key={role.id}>{role.label}</option>)}</select>{mapping && <small>Mapped by {mapping.mappedBy}</small>}</label> })}</section>}
    {similar.length > 0 && <section className="similar-recordings"><div><Waypoints size={17} /><span><strong>Acoustically similar recordings</strong><small>Local rhythm-vector distance</small></span></div>{similar.slice(0, 3).map(item => <span key={item.id}><strong>{item.filename}</strong><small>Distance {item.distance.toFixed(3)} · Priority {item.priorityScore.toFixed(1)}</small></span>)}</section>}
    <section className="annotation-canvas" aria-label="Annotation tiers" style={{ '--tier-label-width': `${tierWidth}px` } as CSSProperties}>
      <div className="canvas-heading"><div><strong>Annotation tiers</strong><span>{space.annotations.length} segments across {space.tiers.length} tiers</span></div><div className="canvas-tools"><button className="icon-button" type="button" disabled={!undoStack.length || saveState === 'saving'} onClick={() => void undo()} title="Undo (Ctrl+Z)" aria-label="Undo"><Undo2 size={16} /></button><button className="icon-button" type="button" disabled={!redoStack.length || saveState === 'saving'} onClick={() => void redo()} title="Redo (Ctrl+Y)" aria-label="Redo"><Redo2 size={16} /></button><label title="Resize tier labels">Tier labels<input type="range" min="95" max="280" value={tierWidth} onChange={event => setTierWidth(Number(event.target.value))} /></label>{requiredMissing.length > 0 && <span className="validation-chip"><CircleAlert size={14} />{requiredMissing.length} required {requiredMissing.length === 1 ? 'tier' : 'tiers'} incomplete</span>}</div></div>
      <div className="overview-timeline" aria-label="Recording overview">{space.annotations.map(item => <button key={item.id} type="button" aria-label={`Jump to ${item.value}`} title={`${item.value} · ${formatTime(item.startMs)}`} onClick={() => setJumpTo({ startMs: item.startMs, endMs: item.endMs, nonce: Date.now() })} style={{ left: `${item.startMs / space.recording.durationMs * 100}%`, width: `${Math.max(.25, (item.endMs - item.startMs) / space.recording.durationMs * 100)}%`, background: space.tiers.find(tier => tier.id === item.tierId)?.color }} />)}</div>
      <div className="timeline-scale"><span>0:00</span><span>{formatTime(space.recording.durationMs / 2)}</span><span>{formatTime(space.recording.durationMs)}</span></div>
      <div className="tier-editor">{space.tiers.map(tier => <div className="tier-track" key={tier.id}><div className="tier-label"><i style={{ background: tier.color }} /><span>{tier.name}{tier.required && <b title="Required tier">*</b>}</span><small>{(grouped.get(tier.id) || []).length}</small></div><div className="tier-lane">{(grouped.get(tier.id) || []).map(item => <button className={editing?.id === item.id ? 'annotation-segment--active' : ''} key={item.id} onClick={() => edit(item)} style={{ left: `${item.startMs / space.recording.durationMs * 100}%`, width: `${Math.max(1, (item.endMs - item.startMs) / space.recording.durationMs * 100)}%`, borderColor: tier.color }} title={`${formatTime(item.startMs)}–${formatTime(item.endMs)}`}>{item.value}</button>)}</div></div>)}{space.tiers.length === 0 && <div className="tier-empty"><CircleAlert size={18} />This project has no tier schema yet.</div>}</div>
    </section>
    {space.canEdit && space.tiers.length > 0 && <form className="annotation-inspector" onSubmit={save}>
      <div className="inspector-heading"><div><span>{editing ? 'Selected segment' : 'New segment'}</span><strong>{editing ? 'Edit annotation' : 'Describe the selected interval'}</strong></div><span className="selection-duration"><Clock3 size={15} />{formatTime(Math.max(0, endMs - startMs))}</span></div>
      <label>Tier<select value={tierId} onChange={event => { setTierId(event.target.value); markChanged() }} required>{space.tiers.map(tier => <option key={tier.id} value={tier.id}>{tier.name}{tier.required ? ' *' : ''}</option>)}</select></label>
      <label>Start<input aria-label="Start time" type="number" min="0" max={space.recording.durationMs / 1000} step="0.001" value={(startMs / 1000).toString()} onChange={event => { setStartMs(Math.round(Number(event.target.value) * 1000)); markChanged() }} required /></label>
      <label>End<input aria-label="End time" type="number" min="0.001" max={space.recording.durationMs / 1000} step="0.001" value={(endMs / 1000).toString()} onChange={event => { setEndMs(Math.round(Number(event.target.value) * 1000)); markChanged() }} required /></label>
      <label className="annotation-value">Annotation{space.tiers.find(t => t.id === tierId)?.type === 'controlled_vocabulary' ? <select name="value" value={value} onChange={event => { setValue(event.target.value); markChanged() }}>{space.tiers.find(t => t.id === tierId)?.values.map(option => <option key={option}>{option}</option>)}</select> : <input name="value" maxLength={4000} value={value} placeholder="Enter annotation value" onChange={event => { setValue(event.target.value); markChanged() }} required />}</label>
      <div className="inspector-actions"><button className="primary-button" type="submit" disabled={invalidRange || !value.trim() || saveState === 'saving'}><Check size={15} />{editing ? 'Save now' : 'Add segment'}</button>{editing && <button className="icon-button danger-button" type="button" onClick={() => void removeAnnotation()} title="Delete annotation" aria-label="Delete annotation"><Trash2 size={16} /></button>}<button className="secondary-button" type="button" onClick={() => { setEditing(null); setValue(''); setSaveState('saved') }}>Clear</button></div>
      {invalidRange && <p className="inline-validation"><CircleAlert size={14} />End time must be after start time and within the recording.</p>}
    </form>}
    {space.canReview && space.recording.taskStatus === 'submitted' && <aside className="review-panel"><div><span>Review decision</span><strong>Is this recording ready for approval?</strong></div><div className="review-actions"><button className="primary-button" onClick={() => void action('review', { decision: 'approved', comment: '' })}><Check size={16} />Approve recording</button><button className="secondary-button" onClick={() => { const comment = window.prompt('Describe the required changes'); if (comment) void action('review', { decision: 'changes_requested', comment }) }}><X size={16} />Request changes</button></div></aside>}
  </div>
}
